:"中间","source_level_label":"3","pinyin":"zhōngjiān","pinyin_plain":"zhongjian","part_of_speech":"名"},{"source_order":983,"hanzi":"终于","source_label":"终于","source_level_label":"3","pinyin":"zhōngyú","pinyin_plain":"zhongyu","part_of_speech":"副"},{"source_order":984,"hanzi":"种","source_label":"种","source_level_label":"3","pinyin":"zhǒng","pinyin_plain":"zhong","part_of_speech":"量"},{"source_order":985,"hanzi":"重要","source_label":"重要","source_level_label":"3","pinyin":"zhòngyào","pinyin_plain":"zhongyao","part_of_speech":"形"},{"source_order":986,"hanzi":"周末","source_label":"周末","source_level_label":"3","pinyin":"zhōumò","pinyin_plain":"zhoumo","part_of_speech":"名"},{"source_order":987,"hanzi":"主要","source_label":"主要","source_level_label":"3","pinyin":"zhǔyào","pinyin_plain":"zhuyao","part_of_speech":"形"},{"source_order":988,"hanzi":"注意","source_label":"注意","source_level_label":"3","pinyin":"zhùyì","pinyin_plain":"zhuyi","part_of_speech":"动"},{"source_order":989,"hanzi":"住院","source_label":"住院","source_level_label":"3","pinyin":"zhùyuàn","pinyin_plain":"zhuyuan","part_of_speech":"动"},{"source_order":990,"hanzi":"字典","source_label":"字典","source_level_label":"3","pinyin":"zìdiǎn","pinyin_plain":"zidian","part_of_speech":"名"},{"source_order":991,"hanzi":"自行车","source_label":"自行车","source_level_label":"3","pinyin":"zìxíngchē","pinyin_plain":"zixingche","part_of_speech":"名"},{"source_order":992,"hanzi":"子","source_label":"子","source_level_label":"3","pinyin":"zi","pinyin_plain":"zi","part_of_speech":"后缀"},{"source_order":993,"hanzi":"总","source_label":"总","source_level_label":"3（5）","pinyin":"zǒng","pinyin_plain":"zong","part_of_speech":"副、（动、形）"},{"source_order":994,"hanzi":"总是","source_label":"总是","source_level_label":"3","pinyin":"zǒngshì","pinyin_plain":"zongshi","part_of_speech":"副"},{"source_order":995,"hanzi":"嘴","source_label":"嘴","source_level_label":"3","pinyin":"zuǐ","pinyin_plain":"zui","part_of_speech":"名"},{"source_order":996,"hanzi":"最好","source_label":"最好","source_level_label":"3","pinyin":"zuìhǎo","pinyin_plain":"zuihao","part_of_speech":"副"},{"source_order":997,"hanzi":"最后","source_label":"最后","source_level_label":"3","pinyin":"zuìhòu","pinyin_plain":"zuihou","part_of_speech":"名"},{"source_order":998,"hanzi":"最近","source_label":"最近","source_level_label":"3","pinyin":"zuìjìn","pinyin_plain":"zuijin","part_of_speech":"名"},{"source_order":999,"hanzi":"做客","source_label":"做客","source_level_label":"3","pinyin":"zuòkè","pinyin_plain":"zuoke","part_of_speech":"动"},{"source_order":1000,"hanzi":"作业","source_label":"作业","source_level_label":"3","pinyin":"zuòyè","pinyin_plain":"zuoye","part_of_speech":"名"}]$catalog$::jsonb) as entry (
